import React, { useEffect, useState } from "react";
import KeyboardBackspaceIcon from "@mui/icons-material/KeyboardBackspace";
import { useNavigate, useParams } from "react-router-dom";
import { Avatar, Box, Button, Tab, Tabs } from "@mui/material";
import BusinessCenterIcon from "@mui/icons-material/BusinessCenter";
import LocationOnIcon from "@mui/icons-material/LocationOn";
import CalendarMonthIcon from "@mui/icons-material/CalendarMonth";
import TabContext from "@mui/lab/TabContext";
import TabList from "@mui/lab/TabList";
import TabPanel from "@mui/lab/TabPanel";
import TweetCard from "../HomeSection/TweetCard";
import ProfileModel from "./ProfileModal";
import { useDispatch, useSelector } from "react-redux";
import { store } from "../../Store/store";
import { findUserById, followUserAction } from "../../Store/Auth/Action";
import { getUsersTweet, findTwitsByLikeContaineUser, findUserReplies } from "../../Store/Twit/Action";
import { connectFeedModerationSocket } from "../../Utils/feedModerationSocket";

const Profile = () => {
  const [tabValue, setTabValue] = useState("1");
  const [moderationTab, setModerationTab] = useState("all"); // all, approved, pending, rejected
  const [visibleUserTwits, setVisibleUserTwits] = useState([]);
  const [visibleReplies, setVisibleReplies] = useState([]);
  const [visibleLiked, setVisibleLiked] = useState([]);
  const navigate = useNavigate();
  const [openProfileModal, setOpenProfileModal] = useState(false);
  const handleOpenProfileModel = () => setOpenProfileModal(true);
  const handleClose = () => setOpenProfileModal(false);
  const { auth,twit } = useSelector((store) => store);
  const dispatch=useDispatch()
  const {id}=useParams()

  const handleBack = () => navigate(-1);

  const handleFollowUser = () => {
    dispatch(followUserAction(id))
    console.log("follow user");
  };
  const handleTabChange = (event, newValue) => {
    setTabValue(newValue);

    if (newValue === "4") {
      // Load danh sách twit mà user này đã like
      dispatch(findTwitsByLikeContaineUser(id));
    } else if (newValue === "2") {
      // Các twit mà user đã reply
      dispatch(findUserReplies(id));
    } else if (newValue === "1") {
      // Twits của user
      dispatch(getUsersTweet(id));
    }
  };

  useEffect(()=>{
dispatch(findUserById(id))
dispatch(getUsersTweet(id))
  },[id])

  useEffect(() => {
    setVisibleUserTwits(twit.twits || []);
  }, [twit.twits]);

  useEffect(() => {
    setVisibleReplies(twit.repliesTwits || []);
  }, [twit.repliesTwits]);

  useEffect(() => {
    setVisibleLiked(twit.likedTwits || []);
  }, [twit.likedTwits]);

  useEffect(() => {
    const disconnect = connectFeedModerationSocket((event) => {
      if (!event || !event.twitId || !event.action) return;
      // Bất kỳ thay đổi moderation nào liên quan tới twit
      // cũng refetch lại toàn bộ dữ liệu profile để đảm bảo trạng thái đúng
      dispatch(getUsersTweet(id));
      dispatch(findUserReplies(id));
      dispatch(findTwitsByLikeContaineUser(id));
    });

    return () => {
      disconnect && disconnect();
    };
  }, [dispatch, id]);

  return (
    <div>
      <section
        className={`bg-white z-50 flex items-center sticky top-0 bg-opacity-95`}
      >
        <KeyboardBackspaceIcon
          className="cursor-pointer"
          onClick={handleBack}
        />

        <p className="py-5 text-xl font-bold opacity-90 ml-5">
          {auth.findUser?.fullName}
        </p>
      </section>

      <section>
        <img
          className="w-[100%] h-[15rem] object-cover"
          src={
            auth.findUser?.backgroundImage
              ? `http://localhost:5454${auth.findUser.backgroundImage}`
              : "https://i.pinimg.com/736x/49/4d/3b/494d3b4fc5dd4a1c83820a6b0598c462.jpg"
          }
          alt="background"
        />
      </section>
      <section className="pl-6">
        <div className="flex justify-between items-start mt-5 h-[5rem]">
          <Avatar
            className="transform -translate-y-24"
            alt={auth.findUser?.fullName || "avatar"}
            src={
              auth.findUser?.image
                ? `http://localhost:5454${auth.findUser.image}`
                : undefined
            }
            sx={{ width: "10rem", height: "10rem", border: "4px solid white" }}
          />
          {auth.findUser?.req_user ? (
            <Button
              onClick={handleOpenProfileModel}
              variant="contained"
              sx={{ borderRadius: "20px" }}
            >
              Edit Profile
            </Button>
          ) : (
            <Button
              onClick={handleFollowUser}
              variant="contained"
              sx={{ borderRadius: "20px" }}
            >
              {auth.findUser?.followed ? "unfollow" : "follow"}
            </Button>
          )}
        </div>
        <div>
          <div className="flex items-center">
            <h1 className="font-bold text-lg">{auth.findUser?.fullName}</h1>
          </div>
          <h1 className="text-gray-500">
            @{auth.findUser?.email || "unknown"}
          </h1>
        </div>

        <div className="mt-2 space-y-3">
          <p>
            {auth.findUser?.bio}
          </p>
          <div className="flex items-center space-x-5">
            <div className="flex items-center space-x-1 font-semibold">
              <span>{auth.findUser?.followings?.length}</span>
              <span className="text-gray-500">Following</span>
            </div>
            <div className="flex items-center space-x-1 font-semibold">
              <span>{auth.findUser?.followers?.length}</span>
              <span className="text-gray-500">Followers</span>
            </div>
          </div>
        </div>
      </section>
      <section className="py-5">
        <Box sx={{ width: "100%", typography: "body1" }}>
          <TabContext value={tabValue}>
            <Box sx={{ borderBottom: 1, borderColor: "divider" }}>
              <TabList
                onChange={handleTabChange}
                aria-label="lab API tabs example"
              >
                <Tab label="Tweets" value="1" />
                <Tab label="Replies" value="2" />
                <Tab label="Media" value="3" />
                <Tab label="Likes" value="4" />
              </TabList>
            </Box>
            <TabPanel value="1">
              {/* Tabs con để lọc theo trạng thái kiểm duyệt */}
              <div className="border-b border-slate-200 mb-2">
                <div className="flex space-x-4 text-sm">
                  <button
                    type="button"
                    className={`pb-2 border-b-2 transition-colors ${
                      moderationTab === "all"
                        ? "border-sky-500 text-sky-600 font-semibold"
                        : "border-transparent text-slate-500 hover:text-slate-700"
                    }`}
                    onClick={() => setModerationTab("all")}
                  >
                    Tất cả
                  </button>
                  <button
                    type="button"
                    className={`pb-2 border-b-2 transition-colors ${
                      moderationTab === "approved"
                        ? "border-sky-500 text-sky-600 font-semibold"
                        : "border-transparent text-slate-500 hover:text-slate-700"
                    }`}
                    onClick={() => setModerationTab("approved")}
                  >
                    Đã được duyệt
                  </button>
                  <button
                    type="button"
                    className={`pb-2 border-b-2 transition-colors ${
                      moderationTab === "pending"
                        ? "border-sky-500 text-sky-600 font-semibold"
                        : "border-transparent text-slate-500 hover:text-slate-700"
                    }`}
                    onClick={() => setModerationTab("pending")}
                  >
                    Đang chờ duyệt
                  </button>
                  <button
                    type="button"
                    className={`pb-2 border-b-2 transition-colors ${
                      moderationTab === "rejected"
                        ? "border-sky-500 text-sky-600 font-semibold"
                        : "border-transparent text-slate-500 hover:text-slate-700"
                    }`}
                    onClick={() => setModerationTab("rejected")}
                  >
                    Đã bị từ chối
                  </button>
                </div>
              </div>

              {(() => {
                const allTwits = visibleUserTwits || [];
                if (allTwits.length === 0) {
                  return <p className="text-gray-500">User này chưa có twit nào.</p>;
                }

                let filtered = allTwits;
                if (moderationTab === "approved") {
                  filtered = allTwits.filter(
                    (t) => !t.moderationStatus || t.moderationStatus === "APPROVED"
                  );
                } else if (moderationTab === "pending") {
                  filtered = allTwits.filter(
                    (t) => t.moderationStatus === "PENDING"
                  );
                } else if (moderationTab === "rejected") {
                  filtered = allTwits.filter(
                    (t) => t.moderationStatus === "REJECTED"
                  );
                }

                if (filtered.length === 0) {
                  return (
                    <p className="text-gray-500">
                      Không có twit nào trong mục này.
                    </p>
                  );
                }

                return (
                  <div className="space-y-4 mt-2">
                    {filtered.map((item) => (
                      <TweetCard key={item.id} item={item} />
                    ))}
                  </div>
                );
              })()}
            </TabPanel>
            <TabPanel value="2">
              {visibleReplies && visibleReplies.length > 0 ? (
                visibleReplies.map((item) => (
                  <TweetCard key={item.id} item={item} />
                ))
              ) : (
                <p className="text-gray-500">User này chưa trả lời twit nào.</p>
              )}
            </TabPanel>
            <TabPanel value="3">Media</TabPanel>
            <TabPanel value="4">
              {visibleLiked && visibleLiked.length > 0 ? (
                visibleLiked.map((item) => (
                  <TweetCard key={item.id} item={item} />
                ))
              ) : (
                <p className="text-gray-500">User này chưa like twit nào.</p>
              )}
            </TabPanel>
          </TabContext>
        </Box>
      </section>
      <section>
        <ProfileModel handleClose={handleClose} open={openProfileModal} />
      </section>
    </div>
  );
};

export default Profile;
